mapper.select:
SELECT COUNT(1)
  FROM COMMON_CODE_GROUP
 WHERE SORT_ORDER = #{sortOrder}


   AND GROUP_CODE != #{groupCode}

mapper.insert:
INSERT INTO COMMON_CODE_GROUP ( /* CommonCodeGroupMapper.addGroupCode (그룹코드 추가) */
            GROUP_CODE
          , GROUP_NAME
          , USE_YN
          , SORT_ORDER
          , CREATE_AT
)    VALUES (
            #{groupCode}
          , #{groupName}
          , #{useYn}
          , #{sortOrder}
          , CURRENT_TIMESTAMP
           )

mapper.update:
UPDATE /* CommonCodeGroupMapper.updateGroupCode (그룹코드 수정) */
       COMMON_CODE_GROUP
   SET GROUP_NAME = #{groupName}
     , USE_YN = #{useYn}
     , SORT_ORDER = #{sortOrder}
     , UPDATE_AT = CURRENT_TIMESTAMP
 WHERE GROUP_CODE = #{groupCode}
